function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var CC={sharp:['[21:20]','"in 216 days"','Sharp','green','216 days','First commit on 2026-04-09.','git log --reverse origin/main'],degraded:['[21:20]','"270-something services"','Degraded','gold','280 surfaces','Right size, wrong unit: say surfaces.','surface-catalog.json'],grain:['[64:07]','The status page has a beliefs view','Unchecked','','Not checked','Not opened live yet.','S1 [64:07]'],slip:['[38:05]','"Frankie Knuckles from Detroit"','Slip','red','Chicago','Harmless in a riff; costly in writing.','general knowledge']};
function kitClaim(s){var c=CC[s];return '<div class="claim '+s+'"><div class="claim-said"><span class="claim-k">You said · '+kEsc(c[0])+'</span><span>'+kEsc(c[1])+'</span></div><span class="chip'+(c[3]?' '+c[3]:'')+'">'+kEsc(c[2])+'</span><div class="claim-record"><span class="claim-v">'+kEsc(c[4])+'</span><span class="claim-note">'+kEsc(c[5])+'</span><span class="ref">'+kEsc(c[6])+'</span></div></div>'}
function kitClaims(host,ss){var w=document.createElement('div');w.className='claims';w.innerHTML=ss.map(kitClaim).join('');host.appendChild(w);return w}
kitClaims(kSlot(),['sharp','degraded','grain','slip']);
STATES.forEach(function(a,i){var b=document.createElement('div');b.style.maxWidth=a[1];kSlot(i).appendChild(b);kitClaims(b,[a[0]])});
